./flake.nix:29:        devShells = "dev";

{ inputs, ... }:
{
  imports = [
    inputs.git-hooks.flakeModule
    inputs.treefmt-nix.flakeModule
  ];

  perSystem =
    {
      agentSandboxChecks,
      config,
      pkgs,
      ...
    }:
    let
      startPodmanService = pkgs.writeShellApplication {
        name = "agent-podman-service";
        runtimeInputs = [
          pkgs.coreutils
          pkgs.gnugrep
          pkgs.podman
          pkgs.systemd
        ];
        text = ''
          runtime_dir="''${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
          socket_dir="$runtime_dir/podman"
          socket="$socket_dir/podman.sock"
          marker=/run/agent-sandbox-podman-delegation

          mkdir -p "$socket_dir"

          # Match the neocache development shell's runtime cgroup delegation.
          # The drop-in and marker live under /run and disappear on reboot.
          if [[ ! -e "$marker" ]]; then
            if [[ " $(id -Gn) " != *" wheel "* ]]; then
              echo 'Podman setup requires membership in the wheel group.' >&2
              exit 1
            fi
            if ! command -v sudo >/dev/null; then
              echo 'Podman setup requires the host sudo wrapper.' >&2
              exit 1
            fi

            echo 'Authorizing ephemeral rootless Podman setup for this boot.' >&2
            sudo -v
            printf '[Service]\nDelegate=cpu cpuset io memory pids\n' \
              | sudo tee /run/systemd/system/user@.service.d/agent-sandbox.conf >/dev/null
            sudo systemctl daemon-reload
            sudo touch "$marker"
          fi

          if [[ -S "$socket" ]]; then
            exit 0
          fi

          if ! systemctl --user is-active --quiet agent-sandbox-podman.service; then
            systemd-run --user --quiet --unit=agent-sandbox-podman \
              --property=Delegate=yes \
              podman --log-level=error system service --time=0 "unix://$socket"
          fi

          for _ in $(seq 1 50); do
            [[ -S "$socket" ]] && exit 0
            sleep 0.1
          done

          echo "Podman's Docker-compatible socket did not appear at $socket" >&2
          exit 1
        '';
      };
    in
    {
      treefmt = {
        projectRootFile = "flake.nix";
        flakeCheck = false;
        programs = {
          actionlint.enable = true;
          deadnix.enable = true;
          nixfmt.enable = true;
          prettier.enable = true;
          rustfmt.enable = true;
          shellcheck.enable = true;
          shfmt.enable = true;
          statix.enable = true;
          taplo.enable = true;
        };
        settings.formatter = {
          # The challenge specification and acceptance scripts are fixtures.
          prettier.excludes = [ "INSTRUCTIONS.md" ];
          shellcheck.includes = [
            "*.sh"
            ".envrc"
          ];
          shfmt.includes = [
            "*.sh"
            ".envrc"
          ];
        };
      };

      pre-commit.settings.hooks = {
        treefmt.enable = true;
        check-added-large-files.enable = true;
        check-merge-conflicts.enable = true;

        flake-check-before-push = {
          enable = true;
          name = "authoritative Nix checks";
          entry = "${pkgs.nix}/bin/nix flake check --print-build-logs";
          always_run = true;
          pass_filenames = false;
          require_serial = true;
          stages = [ "pre-push" ];
        };
      };

      checks = {
        agent-sandbox = agentSandboxChecks.agentPackage;
        agent-image = agentSandboxChecks.agentImage;
        agent-rootfs = agentSandboxChecks.agentRootfs;
        agent-systemd-nspawn = agentSandboxChecks.nspawnApp;
        cargo-clippy = agentSandboxChecks.clippyCheck;
        compose = agentSandboxChecks.composeCheck;
        publish-image = agentSandboxChecks.publishImage;
        sourcehut-manifest = agentSandboxChecks.sourcehutManifestCheck;
      };

      devShells.default = pkgs.mkShell {
        packages = [
          pkgs.cargo
          pkgs.clippy
          pkgs.nixd
          pkgs.podman
          pkgs.podman-compose
          pkgs.rustc
          pkgs.rustfmt
        ];
        shellHook = ''
          ${config.pre-commit.installationScript}
          export XDG_RUNTIME_DIR="''${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
          export DOCKER_HOST="unix://$XDG_RUNTIME_DIR/podman/podman.sock"
          export DOCKER_SOCK="$XDG_RUNTIME_DIR/podman/podman.sock"

          if [[ -z "''${CI:-}" && "''${AGENT_SANDBOX_SKIP_PODMAN_SERVICE:-}" != 1 ]]; then
            ${startPodmanService}/bin/agent-podman-service
          fi
        '';
      };
    };
}

{
  description = "A Nix-built container sandbox for coding agents";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    flake-parts = {
      url = "github:hercules-ci/flake-parts";
      inputs.nixpkgs-lib.follows = "nixpkgs";
    };
  };

  outputs =
    inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      systems = [
        "x86_64-linux"
        "aarch64-linux"
      ];

      imports = [
        inputs.flake-parts.flakeModules.partitions
        ./nix/flake/project.nix
      ];

      # Authoring tools stay out of the package and image input graph.
      partitionedAttrs = {
        checks = "dev";
        devShells = "dev";
        formatter = "dev";
      };

      partitions.dev = {
        extraInputsFlake = ./dev;
        module = import ./nix/flake/dev-partition.nix;
      };
    };
}

{
  config,
  lib,
  pkgs,
  ...
}:
let
  primaryUser = config.dev.johnrinehart.users.primary;
in
{
  imports = [ ./framework.nix ];

  nixpkgs.hostPlatform = "x86_64-linux";
  documentation.nixos.enable = false;

  dev.johnrinehart.boot.loader.systemd-boot = {
    enable = true;
    configurationLimit = 5;
  };

  boot.loader = {
    efi.canTouchEfiVariables = true;
    timeout = 1;
  };

  fonts.fontconfig.enable = lib.mkForce true;
  services.sshd.enable = true;
  programs.ssh.extraConfig = ''
    Host *
      ConnectTimeout 2
  '';
  virtualisation.containers.enable = true;

  users.users.${primaryUser}.extraGroups = [ "input" ];

  # Enable cgroup delegation for the john user's systemd user manager.
  # This is required for running Kubernetes (k3s) inside rootless Podman containers.
  # Without this, k3s fails with "failed to find cpuset cgroup (v2)" because
  # rootless containers don't have access to cgroup controllers by default.
  #
  # The Delegate= directive allows the user's systemd instance to manage its own
  # cgroup subtree, enabling proper resource isolation for containerized workloads.
  # Controllers delegated: cpu, cpuset, io, memory, pids
  #
  # Reference: https://github.com/k3d-io/k3d/issues/1439
  systemd.services."user@".serviceConfig.Delegate = "cpu cpuset io memory pids";

  dev.johnrinehart.system.enable = true;
  dev.johnrinehart.repo-manager.daemon.enable = true;

  dev.johnrinehart.agentTools = {
    enable = true;
    "oh-my-codex".enable = false;
    codexCli.statusLinePlugins = [ "codex-weekly-pace" ];
  };

  dev.johnrinehart.firmware.framework-ec.features = [ "F9-display-toggle" ];
  dev.johnrinehart.firmware.framework-ec.flashService.enable = true;

  dev.johnrinehart.desktop = {
    enable = true;
    variant = "greetd+niri";
    greetd_niri.fingerprint.enable = true;
    obsidian.enable = true;
  };

  # Authenticate before starting Niri so PAM receives the login password and
  # can unlock GNOME Keyring before applications such as Brave are launched.
  # The shared desktop module otherwise starts Niri directly as greetd's
  # unauthenticated default session.

